pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        address nft = address(new ERC721("T", "T"));
        c.initialize(address(0), nft, 1e18, 1e18, 0, 0, bytes32(0), false, false);
        bool ok;
        try c.availableForFlashLoan(nft, 42) returns (bool b) { ok = b; }
        catch { ok = false; }
        bool correct = c.nft() == nft;
        assertTrue(correct);
    }
}

contract ERC721 {
    string public name;
    string public symbol;
    mapping(uint256 => address) internal _ownerOf;
    constructor(string memory _name, string memory _symbol) { name = _name; symbol = _symbol; }
    function mint(address to, uint256 id) external { _ownerOf[id] = to; }
    function ownerOf(uint256 id) external view returns (address) { address o = _ownerOf[id]; require(o != address(0), "NOT_MINTED"); return o; }
}
